package com.greenocean.backend;
import com.greenocean.backend.trust.*;import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.time.*;import java.nio.charset.StandardCharsets;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import com.sun.net.httpserver.HttpServer;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.trust.enabled=true","greenocean.operations.enabled=true","greenocean.operations.alert-worker-enabled=true","greenocean.operations.alert-sweep-ms=3600000","greenocean.operations.alert-escalation-seconds=30"})@ActiveProfiles("test")@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseQ3AlertDeliveryTest extends MigrationTestSupport {
 static final String SCHEMA="qa_q3_delivery_"+UUID.randomUUID().toString().replace("-","");
 static final String SYNTHETIC_KEY="synthetic-qa-alert-signing-key-not-a-real-secret";
 static final AtomicInteger response=new AtomicInteger(202);static final Queue<Map<String,String>> received=new ConcurrentLinkedQueue<>();
 static final AtomicReference<CountDownLatch> holdReceiver=new AtomicReference<>();
 static final HttpServer receiver=start();
 static HttpServer start(){try{var server=HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.setExecutor(Executors.newCachedThreadPool(Thread.ofPlatform().daemon(true).factory()));server.createContext("/",x->{byte[] bytes=x.getRequestBody().readNBytes(4096);try{var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(SYNTHETIC_KEY.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String signature=HexFormat.of().formatHex(mac.doFinal(bytes));received.add(Map.of("payload",new String(bytes,StandardCharsets.UTF_8),"delivery",Objects.toString(x.getRequestHeaders().getFirst("X-GreenOcean-Delivery"),""),"validSignature",String.valueOf(signature.equals(x.getRequestHeaders().getFirst("X-GreenOcean-Signature"))),"path",x.getRequestURI().getPath()));var gate=holdReceiver.get();if(gate!=null)gate.await(3,TimeUnit.SECONDS);x.sendResponseHeaders(response.get(),-1);}catch(Exception failure){x.sendResponseHeaders(500,-1);}finally{x.close();}});server.start();return server;}catch(java.io.IOException unavailable){throw new IllegalStateException(unavailable);}}
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);p.add("greenocean.operations.alert-primary-url",()->"http://127.0.0.1:"+receiver.getAddress().getPort()+"/primary");p.add("greenocean.operations.alert-escalation-url",()->"http://127.0.0.1:"+receiver.getAddress().getPort()+"/escalation");p.add("greenocean.operations.alert-signing-key",()->SYNTHETIC_KEY);}
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired IncidentOperations operations;@Autowired OperationsAlerts alerts;
 PhaseIFixtures.Actor a,b;
 @BeforeEach void setup(){db.update("UPDATE operation_incidents SET state='CLOSED'");db.update("UPDATE operation_alert_routes SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP)");db.update("DELETE FROM audit_logs WHERE action='OPERATION_ALERT_DISPATCH'");PhaseIFixtures.region(db);a=operator();b=operator();received.clear();response.set(202);holdReceiver.set(null);}
 PhaseIFixtures.Actor operator(){var x=PhaseIFixtures.member(db,users,tokens);for(String role:List.of("TRUST_PLATFORM","TRUST_CLINIC"))db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name=?",x.id(),role);db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",x.session());return x;}
 UUID route(String key,int level,PhaseIFixtures.Actor recipient){UUID route=alerts.route(a.id(),a.session(),"CLINIC",recipient.id(),key,level,Instant.now().plusSeconds(3600));alerts.approve(b.id(),b.session(),route);alerts.acknowledgeRoute(recipient.id(),recipient.session(),route);return route;}
 UUID incident(){return operations.detect(a.id(),a.session(),"CLINIC","MEDIA_INTERRUPTION","SEV2",UUID.randomUUID(),"SYNTHETIC:private-evidence-not-in-alert");}
 UUID delivery(UUID incident){return db.queryForObject("SELECT id FROM operation_alerts WHERE incident_id=? ORDER BY created_at,id LIMIT 1",UUID.class,incident);}
 @AfterAll static void cleanup(@Autowired JdbcTemplate db){receiver.stop(0);db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 @Test void realSignedHttpReceiptIsDistinctFromAuthenticatedHumanAcknowledgement(){route("PRIMARY",0,b);UUID incident=incident();alerts.drain();UUID id=delivery(incident);assertThat(received).hasSize(1);var observed=received.peek();assertThat(observed).containsEntry("validSignature","true").containsEntry("delivery",id.toString());assertThat(observed.get("payload")).contains("humanAcknowledgement\":false").doesNotContain(a.id().toString(),b.id().toString(),"private-evidence","body","token","patient");assertThat(db.queryForObject("SELECT state FROM operation_alerts WHERE id=?",String.class,id)).isEqualTo("DELIVERED");assertThat(db.queryForObject("SELECT acknowledged_at FROM operation_alerts WHERE id=?",java.sql.Timestamp.class,id)).isNull();assertThatThrownBy(()->alerts.acknowledge(a.id(),a.session(),id)).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);alerts.acknowledge(b.id(),b.session(),id);assertThat(db.queryForObject("SELECT state FROM operation_alerts WHERE id=?",String.class,id)).isEqualTo("ACKNOWLEDGED");}
 @Test void repeatedWorkerSweepDeduplicatesActualTransport(){route("PRIMARY",0,b);UUID incident=incident();alerts.drain();alerts.drain();assertThat(received).hasSize(1);assertThat(db.queryForObject("SELECT attempts FROM operation_alerts WHERE id=?",Integer.class,delivery(incident))).isEqualTo(1);}
 @Test void providerFailureRetriesSameOpaqueDeliveryAndThenRecordsReceipt(){route("PRIMARY",0,b);UUID incident=incident();response.set(503);alerts.drain();UUID id=delivery(incident);assertThat(db.queryForObject("SELECT state FROM operation_alerts WHERE id=?",String.class,id)).isEqualTo("QUEUED");assertThatThrownBy(()->alerts.acknowledge(b.id(),b.session(),id)).isInstanceOf(com.greenocean.backend.common.exception.ConflictException.class);db.update("UPDATE operation_alerts SET next_attempt_at=CURRENT_TIMESTAMP WHERE id=?",id);response.set(202);alerts.drain();assertThat(received).hasSize(2);assertThat(received.stream().map(r->r.get("delivery")).distinct()).containsExactly(id.toString());assertThat(db.queryForObject("SELECT state FROM operation_alerts WHERE id=?",String.class,id)).isEqualTo("DELIVERED");}
 @Test void retriesStopAtFiveAndFailureRemainsVisible(){route("PRIMARY",0,b);UUID incident=incident();response.set(503);for(int n=0;n<7;n++){db.update("UPDATE operation_alerts SET next_attempt_at=CURRENT_TIMESTAMP WHERE incident_id=?",incident);alerts.drain();}assertThat(received).hasSize(5);assertThat(db.queryForObject("SELECT state FROM operation_alerts WHERE id=?",String.class,delivery(incident))).isEqualTo("FAILED");}
 @Test void missingHumanAcknowledgementEscalatesToCurrentSecondRoute(){route("PRIMARY",0,b);route("ESCALATION",1,a);UUID incident=incident();alerts.drain();assertThat(received).hasSize(1);db.update("UPDATE operation_incidents SET created_at=CURRENT_TIMESTAMP-INTERVAL '31 seconds' WHERE id=?",incident);alerts.drain();assertThat(received).hasSize(2);assertThat(received.stream().map(x->x.get("path"))).containsExactlyInAnyOrder("/primary","/escalation");}
 @Test void actualHumanAcknowledgementPreventsLaterEscalation(){route("PRIMARY",0,b);route("ESCALATION",1,a);UUID incident=incident();alerts.drain();alerts.acknowledge(b.id(),b.session(),delivery(incident));db.update("UPDATE operation_incidents SET created_at=CURRENT_TIMESTAMP-INTERVAL '31 seconds' WHERE id=?",incident);alerts.drain();assertThat(received).hasSize(1);}
 @Test void revokedOrRoleChangedRecipientCannotReceiveNewAlerts(){UUID route=route("PRIMARY",0,b);incident();alerts.revoke(a.id(),a.session(),route);alerts.drain();assertThat(received).isEmpty();route("PRIMARY",0,a);db.update("DELETE FROM user_roles WHERE user_id=? AND role_id=(SELECT id FROM roles WHERE name='TRUST_CLINIC')",b.id());alerts.drain();assertThat(received).isEmpty();}
 @Test void competingWorkersClaimOneActualDelivery()throws Exception{route("PRIMARY",0,b);incident();try(var pool=Executors.newFixedThreadPool(2)){var first=pool.submit(()->alerts.drain());var second=pool.submit(()->alerts.drain());first.get(20,TimeUnit.SECONDS);second.get(20,TimeUnit.SECONDS);}assertThat(received).hasSize(1);}
 @Test void expiredClaimCanBeRecoveredWithTheSameReceiverDeduplicationKey(){UUID route=route("PRIMARY",0,b),incident=incident();UUID id=db.queryForObject("INSERT INTO operation_alerts(incident_id,route_id,state,attempts,claim_id,claimed_at) VALUES(?,?,'CLAIMED',1,?,CURRENT_TIMESTAMP-INTERVAL '40 seconds') RETURNING id",UUID.class,incident,route,UUID.randomUUID());alerts.drain();assertThat(received).hasSize(1);assertThat(received.peek()).containsEntry("delivery",id.toString());assertThat(db.queryForObject("SELECT attempts FROM operation_alerts WHERE id=?",Integer.class,id)).isEqualTo(2);}
 @Test void routeApproverRoleLossAndRecipientAcknowledgementDoNotDeadlock()throws Exception{UUID route=route("PRIMARY",0,a),incident=incident();alerts.drain();UUID id=delivery(incident);try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var ack=pool.submit(()->{start.await();try{alerts.acknowledge(a.id(),a.session(),id);return "ACKNOWLEDGED";}catch(com.greenocean.backend.common.exception.ConflictException revoked){return "REVOKED";}});var revoke=pool.submit(()->{start.await();db.update("DELETE FROM user_roles WHERE user_id=? AND role_id=(SELECT id FROM roles WHERE name='TRUST_CLINIC')",b.id());return "REVOKED";});start.countDown();assertThat(revoke.get(20,TimeUnit.SECONDS)).isEqualTo("REVOKED");assertThat(ack.get(20,TimeUnit.SECONDS)).isIn("ACKNOWLEDGED","REVOKED");}assertThat(db.queryForObject("SELECT revoked_at IS NOT NULL FROM operation_alert_routes WHERE id=?",Boolean.class,route)).isTrue();alerts.drain();assertThat(received).hasSize(1);}
 @Test void slowReceiverDoesNotBlockSchedulerOrQueueUnboundedDuplicateWorkers()throws Exception{route("PRIMARY",0,b);UUID incident=incident();var gate=new CountDownLatch(1);holdReceiver.set(gate);try(var scheduler=Executors.newSingleThreadExecutor()){var returned=scheduler.submit(()->alerts.sweep());returned.get(1,TimeUnit.SECONDS);for(int n=0;n<100&&received.isEmpty();n++)Thread.sleep(20);assertThat(received).hasSize(1);for(int n=0;n<20;n++)alerts.sweep();assertThat(received).hasSize(1);}finally{gate.countDown();holdReceiver.set(null);}String state="";for(int n=0;n<100;n++){state=db.queryForObject("SELECT state FROM operation_alerts WHERE incident_id=?",String.class,incident);if(state.equals("DELIVERED"))break;Thread.sleep(20);}assertThat(state).isEqualTo("DELIVERED");assertThat(received).hasSize(1);}
}
